package com.yumi.cafe.controller;import com.yumi.cafe.dto.OrderResponse;import com.yumi.cafe.service.OrderService;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController{private final OrderService s;private final String key;public AdminController(OrderService s,@Value("${app.admin.key}")String k){this.s=s;key=k;}private void auth(String supplied){if(supplied==null||!supplied.equals(key))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid admin key");}@GetMapping("/orders")public List<OrderResponse> orders(@RequestHeader(value="X-Admin-Key",required=false)String k){auth(k);return s.all();}@PatchMapping("/orders/{number}/status")public OrderResponse status(@RequestHeader(value="X-Admin-Key",required=false)String k,@PathVariable String number,@RequestParam String value){auth(k);return s.updateStatus(number,value);}}
